text:
{
  "hypotheses": [
    {
      "id": "h1",
      "kind": "feature_code",
      "rationale": "Суммарные градусо-дни объединяют отопительную и охлаждающую нагрузку, что напрямую связано с годовым энергопотреблением; отдельные месячные температуры могут не улавливать общий климатический стресс.",
      "patch": {
        "features.custom": [
          "+fe_total_dd"
        ]
      },
      "feature_spec": "fe_total_dd = heating_degree_days_c + cooling_degree_days_c",
      "expected": "Улучшение RMSE за счет более полного учета климатической нагрузки на здание.",
      "cost": "low"
    },
    {
      "id": "h2",
      "kind": "config",
      "rationale": "Таргет сильно скошен (skew=4.76, max=993.4), логарифмическое преобразование уменьшает влияние выбросов и может улучшить RMSE в исходной шкале.",
      "patch": {
        "target.transform": "log1p"
      },
      "feature_spec": null,
      "expected": "Снижение RMSE за счет стабилизации распределения таргета и уменьшения влияния аномально высоких значений.",
      "cost": "low"
    },
    {
      "id": "h3",
      "kind": "model",
      "rationale": "CatBoost лучше обрабатывает пропуски и категориальные признаки (facility_type, State_Factor), а также может дать разнообразие для финального бленда.",
      "patch": {
        "model.name": "catboost",
        "model.params": {
          "learning_rate": 0.05,
          "depth": 6,
          "l2_leaf_reg": 3,
          "iterations": 2000
        }
      },
      "feature_spec": null,
      "expected": "Улучшение RMSE за счет более эффективной работы с пропусками и категориальными признаками.",
      "cost": "medium"
    },
    {
      "id": "h4",
      "kind": "config",
      "rationale": "Target encoding для facility_type (60 категорий) и State_Factor может уловить средние уровни энергопотребления по типам зданий, дополняя native encoding.",
      "patch": {
        "features.builtin": [
          "+target_enc"
        ]
      },
      "feature_spec": null,
      "expected": "Улучшение RMSE за счет более информативного кодирования категориальных признаков с высокой важностью.",
      "cost": "low"
    },
    {
      "id": "h5",
      "kind": "config",
      "rationale": "Пропуски в energy_star_rating (42%) и погодных признаках могут быть информативными; флаги помогут модели различать отсутствие данных.",
      "patch": {
        "preprocess.missing_flags": true
      },
      "feature_spec": null,
      "expected": "Небольшое улучшение RMSE за счет явного учета пропусков в важных признаках.",
      "cost": "low"
    }
  ]
}
